"""Reusable Airtest helpers for image- and text-based screen interaction."""

from __future__ import annotations

import time
from pathlib import Path

import numpy as np
from airtest.core.api import Template
from airtest.core.helper import G
from PIL import Image
from rapidocr import RapidOCR


_IMAGE_TEMPLATE_DIR = str(Path(__file__).resolve().parents[1] / 'assets' / 'img')
if _IMAGE_TEMPLATE_DIR not in G.BASEDIR:
    G.BASEDIR.insert(0, _IMAGE_TEMPLATE_DIR)


class BasePage:
    def __init__(self, device):
        self.device = device
        self._ocr = None

    def _snapshot_upright(self) -> np.ndarray:
        """Return a screenshot aligned with Airtest's touch coordinates."""
        image = Image.fromarray(self.device.snapshot())
        width, height = self.device.get_current_resolution()
        if image.size == (height, width) and width > height:
            image = image.transpose(Image.Transpose.ROTATE_270)
        return np.asarray(image)
    def touch_img(self, image_path: str | Path, timeout: float = 20):
        """Find and click an image template by its name or path."""
        position = self.wait_img(image_path, timeout)
        return self.device.touch(position)

    def touch_extreme_img(image_path, direction="top")
        


    def wait_img(self, image_path: str | Path, timeout: float = 20) -> tuple[int, int]:
        """Wait for an image template to appear and return its center position."""
        template = Template(str(image_path))
        deadline = time.monotonic() + timeout
        while True:
            position = template.match_in(self._snapshot_upright())
            if position is not None:
                return position
            if time.monotonic() >= deadline:
                raise LookupError(f'等待图片模板超时，屏幕上未找到：{image_path}')
            time.sleep(0.25)

    def _find_text_position(self, target: str, timeout: float) -> tuple[int, int] | None:
        deadline = time.monotonic() + timeout
        while True:
            if self._ocr is None:
                self._ocr = RapidOCR()
            result = self._ocr(self._snapshot_upright())
            if result and result.boxes is not None and result.txts:
                matches = [
                    box
                    for box, text in zip(result.boxes, result.txts)
                    if target.casefold() in str(text).casefold()
                ]
                if matches:
                    box = matches[0]
                    center_x = round(sum(float(point[0]) for point in box) / len(box))
                    center_y = round(sum(float(point[1]) for point in box) / len(box))
                    return center_x, center_y

            if time.monotonic() >= deadline:
                return None
            time.sleep(0.25)

    def click_text(self, text: str, timeout: float = 5) -> bool:
        """OCR visible text and tap its center with the connected Airtest device."""
        position = self._find_text_position(text, timeout)
        if position is None:
            raise LookupError(f'屏幕上未找到文字：{text}')
        self.device.touch(position)
        return True

    def touch_text_if_present(self, text: str, timeout: float = 1) -> bool:
        """Tap visible text if it appears before timeout; otherwise do nothing."""
        position = self._find_text_position(text, timeout)
        if position is None:
            return False
        self.device.touch(position)
        return True
        if not match_result:
            return None
        focus_pos = TargetPos().getXY(match_result, self.target_pos)
        return focus_pos

    def match_all_in(self, screen):
        image = self._imread()
        image = self._resize_image(image, screen, ST.RESIZE_METHOD)
        return self._find_all_template(image, screen)

    @logwrap
    def _cv_match(self, screen):
        # in case image file not exist in current directory:
        ori_image = self._imread()
        image = self._resize_image(ori_image, screen, ST.RESIZE_METHOD)
        ret = None
        for method in ST.CVSTRATEGY:
            # get function definition and execute:
            func = MATCHING_METHODS.get(method, None)
            if func is None:
                raise InvalidMatchingMethodError("Undefined method in CVSTRATEGY: '%s', try 'kaze'/'brisk'/'akaze'/'orb'/'surf'/'sift'/'brief' instead." % method)
            else:
                if method in ["mstpl", "gmstpl"]:
                    ret = self._try_match(func, ori_image, screen, threshold=self.threshold, rgb=self.rgb, record_pos=self.record_pos,
                                            resolution=self.resolution, scale_max=self.scale_max, scale_step=self.scale_step)
                else:
                    ret = self._try_match(func, image, screen, threshold=self.threshold, rgb=self.rgb)
            if ret:
                break
        return ret

    @staticmethod
    def _try_match(func, *args, **kwargs):
        G.LOGGING.debug("try match with %s" % func.__name__)
        try:
            ret = func(*args, **kwargs).find_best_result()
        except aircv.NoModuleError as err:
            G.LOGGING.warning("'surf'/'sift'/'brief' is in opencv-contrib module. You can use 'tpl'/'kaze'/'brisk'/'akaze'/'orb' in CVSTRATEGY, or reinstall opencv with the contrib module.")
            return None
        except aircv.BaseError as err:
            G.LOGGING.debug(repr(err))
            return None
        else:
            return ret

    def _imread(self):
        return aircv.imread(self.filepath)

    def _find_all_template(self, image, screen):
        return TemplateMatching(image, screen, threshold=self.threshold, rgb=self.rgb).find_all_results()

    def _find_keypoint_result_in_predict_area(self, func, image, screen):
        if not self.record_pos:
            return None
        # calc predict area in screen
        image_wh, screen_resolution = aircv.get_resolution(image), aircv.get_resolution(screen)
        xmin, ymin, xmax, ymax = Predictor.get_predict_area(self.record_pos, image_wh, self.resolution, screen_resolution)
        # crop predict image from screen
        predict_area = aircv.crop_image(screen, (xmin, ymin, xmax, ymax))
        if not predict_area.any():
            return None
        # keypoint matching in predicted area:
        ret_in_area = func(image, predict_area, threshold=self.threshold, rgb=self.rgb)
        # calc cv ret if found
        if not ret_in_area:
            return None
        ret = deepcopy(ret_in_area)
        if "rectangle" in ret:
            for idx, item in enumerate(ret["rectangle"]):
                ret["rectangle"][idx] = (item[0] + xmin, item[1] + ymin)
